import { Component, DestroyRef, EventEmitter, inject, Input, OnChanges, OnDestroy, Output, ViewEncapsulation } from '@angular/core';
import { FormControl, FormGroup, FormsModule, ReactiveFormsModule, Validators } from '@angular/forms';
import { MatAutocompleteModule, MatAutocompleteSelectedEvent } from '@angular/material/autocomplete';
import { BehaviorSubject } from 'rxjs';
import { filter } from 'rxjs/operators';
import {
    NewPermissionEntity,
    PermissionEntity,
    NewPermission,
    IsSuggestedPermissionEntityValidator,
    InheritedPermissionEntity,
    Permission,
} from '@alfresco/adf-hx-content-services/services';
import { NgIf, NgFor, NgClass, KeyValuePipe } from '@angular/common';
import { MatButtonModule } from '@angular/material/button';
import { MatOptionModule } from '@angular/material/core';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatIconModule } from '@angular/material/icon';
import { MatInputModule } from '@angular/material/input';
import { MatProgressSpinnerModule } from '@angular/material/progress-spinner';
import { MatSelectModule } from '@angular/material/select';
import { TranslateModule } from '@ngx-translate/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { NewPermissionLabels } from '../models/permissions-label.model';

interface AddPermissionForm {
    search: FormControl<string>;
    permission: FormControl<NewPermission | undefined>;
}

@Component({
    selector: 'hxp-add-permission',
    templateUrl: './add-permission.component.html',
    styleUrls: ['./add-permission.component.scss'],
    encapsulation: ViewEncapsulation.None,
    standalone: true,
    imports: [
        MatFormFieldModule,
        MatInputModule,
        FormsModule,
        MatAutocompleteModule,
        ReactiveFormsModule,
        MatIconModule,
        NgIf,
        MatOptionModule,
        MatProgressSpinnerModule,
        NgFor,
        NgClass,
        MatSelectModule,
        MatButtonModule,
        KeyValuePipe,
        TranslateModule,
    ],
})
export class AddPermissionComponent implements OnChanges, OnDestroy {
    private destroyRef = inject(DestroyRef);

    @Input() suggestions: Array<InheritedPermissionEntity> = [];

    @Input() addButtonLabel = '';

    @Input() searchPlaceholderText = '';

    @Input() loading = false;

    @Output() addNewPermission: EventEmitter<NewPermissionEntity> = new EventEmitter();

    @Output() search: EventEmitter<string> = new EventEmitter();

    form: FormGroup<AddPermissionForm>;

    selectedSuggestion?: InheritedPermissionEntity;
    protected permissionLabels = NewPermissionLabels;

    private readonly suggestionsSubject = new BehaviorSubject<PermissionEntity[]>([]);

    constructor(private isSuggestedPermissionEntityValidator: IsSuggestedPermissionEntityValidator) {
        this.form = new FormGroup<AddPermissionForm>(
            {
                search: new FormControl<string>('', {
                    validators: Validators.required,
                    asyncValidators: this.isSuggestedPermissionEntityValidator.createValidator(this.suggestionsSubject.asObservable()),
                    nonNullable: true,
                }),
                permission: new FormControl<NewPermission | undefined>(
                    { value: undefined, disabled: true },
                    {
                        validators: Validators.required,
                        nonNullable: true,
                    }
                ),
            },
            { validators: this.getDisableValidator.bind(this) }
        );
        this.form.controls.search.valueChanges
            .pipe(
                filter((text) => typeof text === 'string'),
                takeUntilDestroyed(this.destroyRef)
            )
            .subscribe({
                next: (text) => {
                    this.search.emit(text.trim());
                },
            });
    }

    ngOnChanges(): void {
        this.suggestionsSubject.next(this.suggestions);
    }

    ngOnDestroy(): void {
        this.suggestionsSubject.complete();
    }

    addPermission() {
        if (this.selectedSuggestion) {
            const { inheritedPermission, ...suggestedEntity } = this.selectedSuggestion;
            const newPermission: NewPermissionEntity = {
                ...suggestedEntity,
                permission: this.form.controls.permission.value as NewPermission,
            };
            this.form.controls.search.patchValue('');
            this.form.controls.permission.patchValue(undefined);
            this.selectedSuggestion = undefined;
            this.form.controls.permission.disable();
            this.addNewPermission.emit(newPermission);
        }
    }

    selectSuggestion(event: MatAutocompleteSelectedEvent) {
        this.selectedSuggestion = event.option.value;
        if (this.selectedSuggestion) {
            this.permissionLabels = this.getAvailablePermissionsOptions(this.selectedSuggestion.inheritedPermission);
            this.form.controls.permission.enable();
        }
    }

    getEntityLabel(entity: PermissionEntity) {
        return entity?.entityLabel ?? '';
    }

    originalOrder = (): number => 0;

    protected suggestionTrackBy(_index: number, suggestion: PermissionEntity) {
        return suggestion.entityId;
    }

    private getAvailablePermissionsOptions(permission?: NewPermission) {
        if (!permission) {
            return NewPermissionLabels;
        }
        const levels: Permission[] = ['None', 'Read', 'ReadWrite', 'Everything'];
        const currentLevel = levels.indexOf(permission);
        const availableOptions: any = {};
        for (const [key, value] of Object.entries(NewPermissionLabels)) {
            const level = levels.indexOf(key as Permission);
            if (level > currentLevel) {
                availableOptions[key] = value;
            }
        }
        return availableOptions;
    }

    private getDisableValidator(): { [key: string]: any } | null {
        if (this.form?.controls?.permission?.disabled) {
            return { isStillDisabled: true };
        }
        // eslint-disable-next-line unicorn/no-null
        return null;
    }
}

import { Component, Inject } from '@angular/core';
import { FormBuilder, FormControlName, ReactiveFormsModule, Validators } from '@angular/forms';
import { MAT_DIALOG_DATA, MatDialogModule } from '@angular/material/dialog';
import { Clipboard } from '@angular/cdk/clipboard';
import {
    ContentShareService,
    HxpNotificationService,
} from '@alfresco/adf-hx-content-services/services';
import { Document } from '@hylandsoftware/hxcs-js-client';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatTooltipModule } from '@angular/material/tooltip';
import { TranslateModule } from '@ngx-translate/core';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatSnackBarModule } from '@angular/material/snack-bar';
import { MatInputModule } from '@angular/material/input';

export interface DialogData {
    sharedDocument: Document;
}
const originFormControlNameNgOnChanges = FormControlName.prototype.ngOnChanges;
FormControlName.prototype.ngOnChanges = function (...arg) {
    const result = originFormControlNameNgOnChanges.apply(this, arg);
    (this.control as any).nativeElement = (
        this.valueAccessor as any
    )?._elementRef?.nativeElement;
    return result;
};

@Component({
    selector: 'hxp-alfresco-dbp-content-share-dialog',
    templateUrl: './content-share-dialog.component.html',
    styleUrls: ['./content-share-dialog.component.scss'],
    standalone: true,
    imports: [
        MatDialogModule,
        MatButtonModule,
        MatTooltipModule,
        MatIconModule,
        MatFormFieldModule,
        ReactiveFormsModule,
        MatInputModule,
        TranslateModule,
        MatSnackBarModule
    ],
})
export class ContentShareDialogComponent {
    readonly shareDocumentForm;

    constructor(
        private readonly _fb: FormBuilder,
        @Inject(MAT_DIALOG_DATA) public data: DialogData,
        public contentShareService: ContentShareService,
        private clipboard: Clipboard,
        private hxpNotificationService: HxpNotificationService
    ) {
        this.shareDocumentForm = this._fb.group({
            shared_link: ['', Validators.required],
        });

        if (this.data?.sharedDocument) {
            const sharedLink =
                this.contentShareService.getSingleContentShareLink(
                    this.data.sharedDocument
                );
            this.shareDocumentForm.patchValue({ shared_link: sharedLink });
        }
    }
    onCopy() {
        this.clipboard.copy(this.shareDocumentForm.value.shared_link ?? '');
        (<any>this.shareDocumentForm.get('shared_link')).nativeElement.select();
        this.hxpNotificationService.openSnackBar(
            'DOCUMENT_SHARE.SNACKBAR.SHARE.SUCCESS',
            'done'
        );
    }
}

import { Component, Inject, ViewEncapsulation } from '@angular/core';
import { MAT_DIALOG_DATA, MatDialogModule, MatDialogRef } from '@angular/material/dialog';
import { PermissionsPanelRequestService } from '@alfresco/adf-hx-content-services/services';
import { MatButtonModule } from '@angular/material/button';
import { TranslateModule } from '@ngx-translate/core';
import { MatRadioModule } from '@angular/material/radio';
import { FormsModule } from '@angular/forms';

export interface DismissPermissionDialogData<T = any> {
    dialogTitle: string;
    dialogDescription: string;
    dialogRejectButton: string;
    dialogConfirmButton: string;
    permissionDialogRef?: MatDialogRef<T>;
}

export abstract class DismissPermission {
    protected abstract close(isEdited: boolean): void;
    protected abstract cancel(isEdited: boolean): void;
}

@Component({
    templateUrl: './confirmation-dialog.component.html',
    styleUrls: ['./confirmation-dialog.component.scss'],
    encapsulation: ViewEncapsulation.None,
    standalone: true,
    imports: [MatDialogModule, MatButtonModule, MatRadioModule, FormsModule, TranslateModule]
})
export class CancelPermissionDialogComponent {

    constructor(
        private dialogRef: MatDialogRef<CancelPermissionDialogComponent>,
        @Inject(MAT_DIALOG_DATA) readonly dialogData: DismissPermissionDialogData,
        private permissionsPanelRequestService: PermissionsPanelRequestService
    ) {}


    reject() {
        this.dialogRef.close();
    }

    confirm() {
        this.dialogRef.close();
        if (this.dialogData?.permissionDialogRef) {
            this.dialogData.permissionDialogRef.close();
        } else {
            this.permissionsPanelRequestService.requestClosePanel();
        }
    }
}

