@use 'mat-selectors' as ms;
@use '@hylandsoftware/design-tokens/scss' as *;

.hxp-permissions-management-panel-container,
.hxp-permissions-management-dialog-container {
    .hxp-add-permission {
        display: flex;
        flex-direction: column;

        .hxp-permission-dialog-input {
            box-sizing: border-box;
            display: flex;
            flex-direction: row;
            justify-content: flex-end;
            align-items: center;
            gap: $hy-spacing-12;
        }

        .hxp-permission-dialog-input-title {
            font-style: normal;
            font-weight: var(--theme-menu-container-font-weight);
            font-size: $hy-font-sizes-20;
            line-height: $hy-line-heights-40;
            color: var(--adf-about-panel-header-title-color);
        }

        .hxp-input-area {
            display: flex;
