import { Document } from '@hylandsoftware/hxcs-js-client';
import { InfoDrawerContentDirective, InfoDrawerLayoutComponent } from '@alfresco/adf-core';
import { DocumentRouterService, DocumentVersionsService, VersionableDocument, UserResolverPipe } from '@alfresco/adf-hx-content-services/services';
import { DatePipe, NgFor, NgIf } from '@angular/common';
import { Component, EventEmitter, Input, OnInit, Output, ViewEncapsulation } from '@angular/core';
import { TranslateModule } from '@ngx-translate/core';
import { MatIconModule } from '@angular/material/icon';
import { finalize, map, switchMap, take } from 'rxjs';
import { MatButtonModule } from '@angular/material/button';
import { MatMenuModule } from '@angular/material/menu';
import { PanelSkeletonLoaderComponent } from '../../skeleton-loader/panel-skeleton-loader/panel-skeleton-loader.component';
import { MatTooltipModule } from '@angular/material/tooltip';

@Component({
    selector: 'hxp-manage-versions-sidebar',
    standalone: true,
    encapsulation: ViewEncapsulation.None,
    imports: [
        NgIf,
        NgFor,
        TranslateModule,
        UserResolverPipe,
        DatePipe,
        InfoDrawerLayoutComponent,
        InfoDrawerContentDirective,
        MatButtonModule,
        MatIconModule,
        PanelSkeletonLoaderComponent,
        MatMenuModule,
        MatTooltipModule,
    ],
    templateUrl: './manage-versions-sidebar.component.html',
    styleUrls: ['./manage-versions-sidebar.component.scss'],
})
export class ManageVersionsSidebarComponent implements OnInit {
    /**
     * The document to display the versions for
     * @type {Document}
     */
    @Input() document?: Document;
    /**
     * Emits an event when the sidebar is closed
     */
    @Output() closeVersionsSidebar = new EventEmitter<void>();

    public documentVersions: VersionableDocument[] = [];
    isLoading = false;

    constructor(private documentRouterService: DocumentRouterService, private documentVersionsService: DocumentVersionsService) {}

    ngOnInit() {
        this.loadVersions();
    }

    redirectToVersion(document: Document): void {
        if (document) {
            this.documentRouterService.navigateTo(document);
        }
    }

    protected onClose(): void {
        this.closeVersionsSidebar.emit();
    }

    private loadVersions() {
        if (!this.document) {
            return;
        }
        this.isLoading = true;
        this.documentVersionsService
            .getCurrentDocument(this.document)
            .pipe(
                take(1),
                switchMap((currentDoc) =>
                    this.documentVersionsService.getVersions(currentDoc).pipe(map((versions: VersionableDocument[]) => [currentDoc, ...versions]))
                ),
                finalize(() => (this.isLoading = false))
            )
            .subscribe({
                next: (mergedVersions: VersionableDocument[]) => {
                    this.documentVersions = mergedVersions;
                },
                error: (err) => {
                    console.error(err);
                },
            });
    }
}

